// Delney, Streetwise Lookout
// status: ready
// Creatures you control with power 2 or less can't be blocked by creatures with power 3 or greater.
// If a triggered ability of a creature you control with power 2 or less triggers, that ability triggers an additional time.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); ((*so_far).is(CardType::Creature) && Some(asker.controller) == Some(q.controller(affected)) && (*so_far).power.is_some_and(|v| (i64::from(v)) <= (2i64))) }
#[allow(unused_variables)] fn ability_0_0_rule(q: &dyn Query, source: ObjectId, blocker: ObjectId, attacker: ObjectId) -> bool { let asker = &Asker::new(source, q.controller(source)); !((q.chars(attacker).is(CardType::Creature) && Some(asker.controller) == Some(q.controller(attacker)) && q.chars(attacker).power.is_some_and(|v| (i64::from(v)) <= (2i64))) && (q.chars(blocker).is(CardType::Creature) && q.chars(blocker).power.is_some_and(|v| (i64::from(v)) >= (3i64)))) }
#[allow(unused_variables)] fn ability_1_trigger_rule(q: &dyn Query, asker: &Asker, event: &Event, triggering: &Triggering) -> bool { (triggering.permanent && (q.chars(triggering.source).is(CardType::Creature) && Some(asker.controller) == Some(triggering.controller) && q.chars(triggering.source).power.is_some_and(|v| (i64::from(v)) <= (2i64)))) && true }

